{
  "name": "INHECO Thermoshake AC恒温振荡器",
  "name_en": "INHECO Thermoshake AC heater-shaker",
  "manufacturer": "INHECO",
  "description": "这是一种实验室恒温振荡器，用于对样品板等容器进行加热与振荡混匀。设备可设置振荡转速和振荡轨迹，部分操作还包括样品板锁定/解锁，常用于样品孵育、混匀及温控处理。",
  "description_en": "This is a laboratory heater-shaker used to heat and shake sample plates and similar labware for mixing. It supports setting shaking speed and motion pattern, and some operations include plate locking/unlocking, making it suitable for incubation, mixing, and temperature-controlled sample handling.",
  "actions": [
    {
      "action_name": "auto-start_shaking",
      "description": "开始按已设定参数进行振荡。",
      "description_en": "Start shaking using the currently configured settings."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-set_shaker_speed",
      "description": "设置振荡转速。",
      "description_en": "Set the shaking speed."
    },
    {
      "action_name": "auto-set_shaker_shape",
      "description": "设置振荡轨迹形状。",
      "description_en": "Set the shaking motion pattern."
    },
    {
      "action_name": "auto-shake",
      "description": "以指定转速和轨迹开始振荡。",
      "description_en": "Start shaking at the specified speed and motion pattern."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "检查设备是否支持样品板锁定功能。",
      "description_en": "Check whether the device supports plate locking."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定样品板。",
      "description_en": "Lock the plate."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁样品板。",
      "description_en": "Unlock the plate."
    }
  ],
  "tag_hints": [
    "heater-shaker",
    "microplate shaking",
    "sample incubation",
    "temperature control",
    "plate locking",
    "orbital mixing",
    "INHECO Thermoshake"
  ]
}

